1	import React, { useState, useEffect } from 'react';
2	import { getRelatorio, getMinhaEmpresa, getCaixa, getCaixaHistorico, aprovarConferencia, getConfig } from '../../services/restauranteService';
3	import Icon from '../../components/AppIcon';
4	import CaixaAtualPanel from './CaixaAtualPanel';
5	import HistoricoCaixasPanel from './HistoricoCaixasPanel';
6	import RestauranteHeader from '../../components/restaurante/RestauranteHeader';
7	
8	const fmt      = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
9	const fmtDate  = (d) => d ? new Date(d).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
10	const today    = () => new Date().toISOString().slice(0, 10);
11	const thisMonth = () => new Date().toISOString().slice(0, 7);
12	const thisYear  = () => new Date().getFullYear().toString();
13	const startOf   = (d) => new Date(d + 'T00:00:00-03:00').toISOString();
14	const endOf     = (d) => new Date(d + 'T23:59:59-03:00').toISOString();
15	const lastDay   = (ym) => { const [y, m] = ym.split('-').map(Number); return new Date(y, m, 0).getDate(); };
16	const ANOS      = Array.from({ length: 4 }, (_, i) => String(new Date().getFullYear() - i));
17	const MODOS     = [{ value: 'dia', label: 'Dia' }, { value: 'mes', label: 'Mês' }, { value: 'ano', label: 'Ano' }, { value: 'periodo', label: 'Período' }];
18	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', cash: 'Dinheiro', taxa_cartao: '+ Taxa cartão' };
19	const PAYMENT_ICONS  = { pix: 'QrCode', credit_card: 'CreditCard', debit_card: 'CreditCard', cash: 'Banknote' };
20	const PAYMENT_COLORS = { pix: 'border-blue-200 bg-blue-50 text-blue-800', credit_card: 'border-purple-200 bg-purple-50 text-purple-800', debit_card: 'border-indigo-200 bg-indigo-50 text-indigo-800', cash: 'border-green-200 bg-green-50 text-green-800' };
21	const STATUS_LABELS  = { pending: 'Recebido', confirmed: 'Confirmado', preparing: 'Em Preparo', ready: 'Pronto', motoboy_collecting: 'Motoboy', out_for_delivery: 'Em Entrega', delivered: 'Entregue', canceled: 'Cancelado' };
22	const STATUS_COLORS  = { pending: 'bg-yellow-100 text-yellow-800', confirmed: 'bg-blue-100 text-blue-800', preparing: 'bg-orange-100 text-orange-800', ready: 'bg-purple-100 text-purple-800', motoboy_collecting: 'bg-sky-100 text-sky-800', out_for_delivery: 'bg-indigo-100 text-indigo-800', delivered: 'bg-green-100 text-green-800', canceled: 'bg-red-100 text-red-800' };
23	
24	const PRINT_STYLE = `*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:12px;padding:16px;max-width:800px;margin:0 auto}h1{font-size:18px;font-weight:900;margin-bottom:2px}h2{font-size:13px;font-weight:700;margin:14px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px}.sub{font-size:11px;color:#555;margin-bottom:12px}table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px}th{background:#f0f0f0;padding:6px 8px;text-align:left;font-weight:700;border:1px solid #ddd}td{padding:5px 8px;border:1px solid #ddd}.right{text-align:right}.bold{font-weight:700}.green{color:#166534}.red{color:#991b1b}.kpi{display:inline-block;border:1px solid #ddd;border-radius:6px;padding:8px 14px;margin:4px;text-align:center;min-width:120px}.kpi .val{font-size:18px;font-weight:900;display:block}.kpi .lbl{font-size:10px;color:#555}@media print{button{display:none!important}}`;
25	const buildPrint = (dados, nome, label) => {
26	  const r = dados.resumo;
27	  const pgto = Object.entries(r.por_pagamento ?? {}).map(([k, v]) => `<tr><td>${PAYMENT_LABELS[k] ?? k}</td><td class="right">${v.count}</td><td class="right bold green">${fmt(v.total)}</td></tr>`).join('');
28	  const saidasRows = (dados.saidas ?? []).map((s) => `<tr><td>${fmtDate(s.criado_em)}</td><td>${s.descricao}</td><td class="right bold red">- ${fmt(s.valor)}</td></tr>`).join('');
29	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Financeiro</title><style>${PRINT_STYLE}</style></head><body><h1>${nome ?? 'RESTAURANTE'}</h1><div class="sub">Relatório Financeiro — ${label}</div><div><div class="kpi"><span class="val green">${fmt(r.total_vendas)}</span><span class="lbl">Faturamento</span></div><div class="kpi"><span class="val red">- ${fmt(r.total_saidas)}</span><span class="lbl">Saídas</span></div><div class="kpi"><span class="val">${fmt(r.saldo_liquido)}</span><span class="lbl">Saldo Líquido</span></div><div class="kpi"><span class="val">${r.total_pedidos}</span><span class="lbl">Pedidos</span></div></div><h2>Por Forma de Pagamento</h2><table><tr><th>Método</th><th class="right">Qtd</th><th class="right">Total</th></tr>${pgto}</table>${(dados.saidas ?? []).length > 0 ? `<h2>Saídas</h2><table><tr><th>Data</th><th>Descrição</th><th class="right">Valor</th></tr>${saidasRows}</table>` : ''}<footer>Emitido em: ${new Date().toLocaleString('pt-BR')}</footer><script>window.print();setTimeout(()=>{try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}},2000)</script></body></html>`;
30	};
31	const printIframe = (html) => {
32	  const f = document.createElement('iframe');
33	  f.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
34	  document.body.appendChild(f);
35	  try { f.contentDocument.open(); f.contentDocument.write(html); f.contentDocument.close(); }
36	  catch { f.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
37	};
38	
39	const buildRange = (modo, dia, mes, ano, ini, fim) => {
40	  if (modo === 'dia')     return { de: startOf(dia), ate: endOf(dia), label: new Date(dia + 'T12:00:00').toLocaleDateString('pt-BR') };
41	  if (modo === 'mes') { const [y, m] = mes.split('-'); return { de: startOf(`${y}-${m}-01`), ate: endOf(`${y}-${m}-${String(lastDay(mes)).padStart(2, '0')}`), label: new Date(mes + '-01T12:00:00').toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }) }; }
42	  if (modo === 'ano')     return { de: startOf(`${ano}-01-01`), ate: endOf(`${ano}-12-31`), label: `Ano ${ano}` };
43	  if (modo === 'periodo') return { de: startOf(ini), ate: endOf(fim), label: `${new Date(ini + 'T12:00:00').toLocaleDateString('pt-BR')} a ${new Date(fim + 'T12:00:00').toLocaleDateString('pt-BR')}` };
44	  return null;
45	};
