47	const RestauranteFinanceiro = () => {
48	  const [restauranteNome, setRestauranteNome] = useState('');
49	  const [modo, setModo] = useState('dia');
50	  const [dia, setDia]   = useState(today());
51	  const [mes, setMes]   = useState(thisMonth());
52	  const [ano, setAno]   = useState(thisYear());
53	  const [ini, setIni]   = useState(today());
54	  const [fim, setFim]   = useState(today());
55	  const [dados, setDados]     = useState(null);
56	  const [label, setLabel]     = useState('');
57	  const [loading, setLoading] = useState(false);
58	  const [erro, setErro]       = useState(null);
59	  const [abaAtiva, setAbaAtiva] = useState('resumo');
60	  const [caixa, setCaixa]     = useState(null);
61	  const [historico, setHistorico] = useState([]);
62	  const [aprovando, setAprovando] = useState(null);
63	  const [taxaPagbank, setTaxaPagbank] = useState(0);
64	
65	  const conferenciasPendentes = historico.filter(
66	    (cx) => cx.status === 'fechado' && cx.destinacao_fechamento?.conferencia_aprovada === false,
67	  );
68	
69	  const carregarDados = async () => {
70	    const [c, hist] = await Promise.all([getCaixa(), getCaixaHistorico()]);
71	    setCaixa(c);
72	    setHistorico(hist.historico ?? []);
73	  };
74	
75	  useEffect(() => {
76	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
77	    getConfig().then((cfg) => setTaxaPagbank(cfg.taxa_pagbank_percent ?? 0)).catch(() => {});
78	    carregarDados().catch(() => {});
79	    buscar();
80	  }, []); // eslint-disable-line
81	
82	  const buscar = async () => {
83	    const range = buildRange(modo, dia, mes, ano, ini, fim);
84	    if (!range) return;
85	    setLoading(true); setErro(null);
86	    try { const d = await getRelatorio(range.de, range.ate); setDados(d); setLabel(range.label); }
87	    catch (e) { setErro(e.message); }
88	    finally { setLoading(false); }
89	  };
90	
91	  const handleAprovarConferencia = async (caixaId) => {
92	    setAprovando(caixaId);
93	    try { await aprovarConferencia(caixaId); await carregarDados(); }
94	    catch (e) { alert(e.message ?? 'Erro ao aprovar'); }
95	    finally { setAprovando(null); }
96	  };
97	
98	  const r = dados?.resumo;
99	  const cashTotal    = r?.por_pagamento?.cash?.total ?? 0;
100	  const digitalTotal = Object.entries(r?.por_pagamento ?? {}).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v.total, 0);
101	
102	  return (
103	    <div className="min-h-screen bg-[#FAFAFA]">
104	      <RestauranteHeader active="/restaurante/financeiro" title="Financeiro" subtitle="Gestão financeira gerencial" />
105	
106	      <main className="p-6 w-[95%] mx-auto max-w-5xl space-y-5">
107	
108	        {/* Caixa Atual */}
109	        {caixa?.aberto
110	          ? <CaixaAtualPanel caixa={caixa} taxaPagbank={taxaPagbank} onRefresh={carregarDados} />
111	          : caixa && (
