114	                <Icon name="Lock" size={18} className="text-[#A1A1AA]" />
115	              </div>
116	              <div>
117	                <p className="text-sm font-bold text-[#18181B]">Caixa Fechado</p>
118	                <p className="text-xs text-[#71717A]">Abra o caixa no Dashboard para iniciar uma sessão.</p>
119	              </div>
120	            </div>
121	          )
122	        }
123	
124	        {/* Conferências Pendentes */}
125	        {conferenciasPendentes.length > 0 && (
126	          <div className="bg-white rounded-2xl border border-amber-200 p-5">
127	            <p className="text-sm font-bold text-[#18181B] mb-1">Conferências Pendentes</p>
