173	            {modo === 'periodo' && (
174	              <>
175	                <input type="date" value={ini} onChange={(e) => setIni(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
176	                <span className="text-sm text-[#71717A] self-center">até</span>
177	                <input type="date" value={fim} min={ini} onChange={(e) => setFim(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
