187	                className="flex items-center gap-2 px-4 py-2 border border-[#E4E4E7] rounded-xl text-sm font-bold text-[#27272A] hover:bg-[#F4F4F5]">
188	                <Icon name="Printer" size={14} /> Imprimir
189	              </button>
190	            )}
191	          </div>
192	          {erro && <p className="text-sm text-red-600 bg-red-50 px-3 py-2 rounded-xl mt-3">{erro}</p>}
193	        </div>
194	
195	        {dados && r && (
196	          <>
197	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
198	              <div className="bg-white border border-green-200 rounded-2xl p-4 text-center">
199	                <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Faturamento</p>
200	                <p className="text-2xl font-black text-green-700">{fmt(r.total_vendas)}</p>
201	                <p className="text-xs text-[#71717A] mt-1">{r.entregues} pedidos entregues</p>
202	              </div>
203	              <div className="bg-white border border-red-200 rounded-2xl p-4 text-center">
204	                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
205	                <p className="text-2xl font-black text-red-600">- {fmt(r.total_saidas)}</p>
206	                <p className="text-xs text-[#71717A] mt-1">{(dados.saidas ?? []).length} registros</p>
207	              </div>
208	              <div className={`bg-white border rounded-2xl p-4 text-center ${r.saldo_liquido >= 0 ? 'border-[#FF441F]/30' : 'border-red-200'}`}>
209	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Saldo Líquido</p>
210	                <p className={`text-2xl font-black ${r.saldo_liquido >= 0 ? 'text-[#FF441F]' : 'text-red-600'}`}>{fmt(r.saldo_liquido)}</p>
211	                <p className="text-xs text-[#71717A] mt-1">Faturamento − Saídas</p>
212	              </div>
213	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
214	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Ticket Médio</p>
215	                <p className="text-2xl font-black text-[#18181B]">{fmt(r.ticket_medio)}</p>
216	                <p className="text-xs text-[#71717A] mt-1">{r.total_pedidos} pedidos total</p>
217	              </div>
218	            </div>
219	
220	            <div className="flex gap-1 bg-[#F4F4F5] p-1 rounded-xl w-fit">
221	              {[{ id: 'resumo', label: 'Entradas' }, { id: 'canais', label: 'Canais' }, { id: 'saidas', label: `Saídas (${(dados.saidas ?? []).length})` }, { id: 'pedidos', label: `Pedidos (${dados.pedidos?.length ?? 0})` }].map((a) => (
222	                <button key={a.id} onClick={() => setAbaAtiva(a.id)}
223	                  className={`px-4 py-2 text-xs font-bold rounded-lg transition-colors ${abaAtiva === a.id ? 'bg-white text-[#18181B] shadow-sm' : 'text-[#71717A] hover:text-[#27272A]'}`}>
224	                  {a.label}
225	                </button>
