236	                      <p className="text-2xl font-black">{fmt(v.total)}</p>
237	                      <p className="text-xs mt-1 opacity-70">{v.count} pedido{v.count !== 1 ? 's' : ''}</p>
238	                    </div>
239	                  ))}
240	              </div>
241	            )}
242	
243	            {abaAtiva === 'canais' && (
244	              <div className="grid md:grid-cols-2 gap-4">
245	                <div className="bg-white border border-green-200 rounded-2xl p-5">
246	                  <div className="flex items-center gap-2 mb-3"><Icon name="Banknote" size={18} className="text-green-600" /><h3 className="font-bold text-[#18181B]">Dinheiro Físico (Caixa)</h3></div>
247	                  <p className="text-3xl font-black text-green-700 mb-1">{fmt(cashTotal)}</p>
248	                  <p className="text-xs text-[#71717A]">{r.por_pagamento?.cash?.count ?? 0} pagamentos em dinheiro</p>
249	                  <div className="mt-4 pt-3 border-t border-green-100">
250	                    <p className="text-xs font-semibold text-green-700">Estimativa em caixa: {fmt(Math.max(0, cashTotal - r.total_saidas))}</p>
251	                  </div>
252	                </div>
253	                <div className="bg-white border border-blue-200 rounded-2xl p-5">
