257	                  <div className="mt-4 pt-3 border-t border-blue-100 space-y-1">
258	                    {Object.entries(r.por_pagamento ?? {}).filter(([k]) => k !== 'cash').map(([k, v]) => (
259	                      <div key={k} className="flex justify-between text-xs"><span className="text-[#71717A]">{PAYMENT_LABELS[k] ?? k}</span><span className="font-semibold">{fmt(v.total)} ({v.count})</span></div>
260	                    ))}
261	                  </div>
262	                </div>
263	              </div>
