265	
266	            {abaAtiva === 'saidas' && (
267	              <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
268	                {(dados.saidas ?? []).length === 0
269	                  ? <p className="text-sm text-[#71717A] text-center py-10">Nenhuma saída registrada no período.</p>
270	                  : (
271	                    <div>
272	                      <div className="px-5 py-3 bg-[#FAFAFA] border-b border-[#F4F4F5] flex justify-between text-xs font-bold text-[#71717A] uppercase tracking-widest"><span>Data / Descrição</span><span>Valor</span></div>
273	                      <div className="divide-y divide-[#F4F4F5] max-h-[400px] overflow-y-auto">
274	                        {(dados.saidas ?? []).sort((a, b) => new Date(b.criado_em) - new Date(a.criado_em)).map((s, i) => (
275	                          <div key={i} className="flex items-center justify-between px-5 py-3">
276	                            <div><p className="text-sm font-semibold text-[#18181B]">{s.descricao}</p><p className="text-xs text-[#71717A]">{fmtDate(s.criado_em)}{s.meio && <span className="ml-1.5 px-1.5 py-0.5 bg-[#F4F4F5] rounded text-[10px] capitalize">{s.meio}</span>}</p></div>
277	                            <p className="font-bold text-red-500 text-sm flex-shrink-0">- {fmt(s.valor)}</p>
278	                          </div>
279	                        ))}
280	                      </div>
281	                      <div className="px-5 py-3 bg-red-50 border-t border-red-100 flex justify-between"><span className="text-sm font-bold text-red-700">Total saídas</span><span className="text-sm font-black text-red-700">- {fmt(r.total_saidas)}</span></div>
282	                    </div>
283	                  )}
284	              </div>
285	            )}
286	
287	            {abaAtiva === 'pedidos' && (
288	              <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
289	                {(dados.pedidos ?? []).length === 0
290	                  ? <p className="text-sm text-[#71717A] text-center py-10">Nenhum pedido no período.</p>
291	                  : (
292	                    <div>
293	                      <div className="px-5 py-3 bg-[#FAFAFA] border-b border-[#F4F4F5] grid grid-cols-4 text-xs font-bold text-[#71717A] uppercase tracking-widest"><span>Pedido</span><span>Cliente</span><span>Pagamento</span><span className="text-right">Total</span></div>
294	                      <div className="divide-y divide-[#F4F4F5] max-h-[500px] overflow-y-auto">
295	                        {dados.pedidos.map((p) => (
296	                          <div key={p.id} className="px-5 py-3 grid grid-cols-4 items-center gap-2 hover:bg-[#FAFAFA]">
297	                            <div><div className="flex items-center gap-1.5"><span className="text-sm font-bold">#{p.id}</span><span className={`text-[9px] px-1.5 py-0.5 rounded-full font-semibold ${STATUS_COLORS[p.status] ?? 'bg-gray-100 text-gray-700'}`}>{STATUS_LABELS[p.status] ?? p.status}</span></div><p className="text-[10px] text-[#71717A]">{fmtDate(p.created_at)}</p></div>
298	                            <p className="text-xs truncate">{p.customers?.name ?? '—'}</p>
299	                            <p className="text-xs text-[#71717A]">{PAYMENT_LABELS[p.payment_method] ?? p.payment_method}</p>
300	                            <p className={`text-sm font-bold text-right ${p.status === 'canceled' ? 'text-red-400 line-through' : 'text-[#18181B]'}`}>{fmt(p.total)}</p>
301	                          </div>
302	                        ))}
303	                      </div>
304	                      <div className="px-5 py-3 bg-[#FAFAFA] border-t border-[#E4E4E7] flex justify-between"><span className="text-sm text-[#71717A]">{dados.pedidos.length} pedidos · {r.cancelados} cancelados</span><span className="text-sm font-black text-green-700">{fmt(r.total_vendas)} faturados</span></div>
305	                    </div>
306	                  )}
