309	          </>
310	        )}
311	
312	        {!dados && !loading && (
313	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-10 text-center">
314	            <Icon name="BarChart2" size={32} className="text-[#D4D4D8] mx-auto mb-3" />
315	            <p className="text-[#71717A]">Selecione o período e clique em Buscar.</p>
316	          </div>
317	        )}
318	
319	        {/* Histórico de Caixas */}
320	        <HistoricoCaixasPanel historico={historico} />
321	
322	      </main>
323	    </div>
324	  );
325	};
326	
327	export default RestauranteFinanceiro;
