975	  private calcularResumo(
976	    pedidos: any[],
977	    saidas: any[],
978	    valor_inicial: number,
979	    entradas: any[] = [],
980	    pagamentosPorComanda?: Map<number, { valor: number; valor_recebido?: number | null; forma_pagamento: string; taxa_cartao_valor?: number }[]>,
981	  ) {
982	    const entregues = pedidos.filter((p) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
983	    const total_saidas = saidas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
984	    const total_entradas = entradas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
985	
986	    // orders.total (comanda do salão) guarda só subtotal-desconto+acréscimo — a taxa de
987	    // cartão cobrada do cliente fica em comanda_pagamentos.taxa_cartao_valor. Entra num
988	    // bucket "taxa_cartao" à parte (não somado dentro de Cartão Crédito/Débito) pra
989	    // aparecer explícito na conferência de fechamento, sem esconder dentro da forma.
990	    let total_vendas = 0;
991	    const por_pagamento: Record<string, number> = {};
992	    // Taxa por forma (não some no bucket único "taxa_cartao") — pra tela de fechamento
993	    // poder mostrar "Débito R$161,70 + taxa R$11,32 = R$173,02" em vez de um total
994	    // de taxa solto, sem saber se veio do débito ou do crédito.
995	    const taxa_por_forma: Record<string, number> = {};
996	    // Dinheiro que o cliente entregou de fato (valor_recebido) — só pra exibição na
997	    // conferência de fechamento. O que entra/sai fisicamente do caixa já é lançado como
998	    // entrada/saída no ledger (ver registrarEntradaCaixa/registrarSaidaCaixa em
999	    // salao.service.ts), então especie_calculada usa entradas_especie/saidas_especie,
1000	    // não esse valor — contar os dois juntos duplicaria a entrada em espécie.
1001	    let cash_recebido = 0;
1002	    for (const p of entregues) {
1003	      const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComanda?.get(p.id) : undefined;
1004	      if (pagamentosComanda?.length) {
1005	        for (const pag of pagamentosComanda) {
1006	          const m = pag.forma_pagamento ?? 'outro';
1007	          const taxa = pag.taxa_cartao_valor ?? 0;
1008	          por_pagamento[m] = (por_pagamento[m] ?? 0) + (pag.valor ?? 0);
1009	          if (taxa > 0) {
1010	            por_pagamento['taxa_cartao'] = (por_pagamento['taxa_cartao'] ?? 0) + taxa;
1011	            taxa_por_forma[m] = (taxa_por_forma[m] ?? 0) + taxa;
1012	          }
1013	          total_vendas += (pag.valor ?? 0) + taxa;
1014	          if (m === 'cash') cash_recebido += pag.valor_recebido ?? pag.valor ?? 0;
1015	        }
1016	      } else {
1017	        const m = p.payment_method ?? 'outro';
1018	        por_pagamento[m] = (por_pagamento[m] ?? 0) + (p.total ?? 0);
1019	        total_vendas += p.total ?? 0;
1020	        if (m === 'cash') cash_recebido += p.total ?? 0;
1021	      }
1022	    }
1023	
1024	    const saidas_especie = saidas
1025	      .filter((s: any) => !s.meio || s.meio === 'dinheiro')
1026	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
1027	    const entradas_especie = entradas
1028	      .filter((e: any) => !e.meio || e.meio === 'dinheiro')
1029	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);

